/**
 * playerStatsTypes.ts — Types and loader for pre-computed player stats
 *
 * Data comes from player-stats.json, generated by enrich-players.js
 * Used by: CompararPage (badges, rankings), JogadoresPage (sidebar alerts)
 */
import { cachedFetchJson, memoAsync } from "./fetchCache";

export interface PlayerStats {
  lastRoundDate: string | null;
  roundsTotal: number;
  /** Rondas no ano civil corrente (Jan→hoje). Mesma fonte que o detalhe da
   *  ficha do jogador — calculado a partir de data.json (canónico). */
  roundsCurrentYear: number;
  roundsLast3m: number;
  roundsLast6m: number;
  roundsLast12m: number;
  avgSD5: number | null;
  avgSD8: number | null;     // best 8 of last 20 — "power ranking" metric
  avgSD20: number | null;
  lastSD: number | null;
  currentHcp: number | null;
  hcpTrend: "up" | "stable" | "down";  // up = improving (HCP ↓)
  hcpDelta3m: number | null;
  formAlert: "hot" | "cold" | null;
  bestGross: number | null;
  avgGross5: number | null;
  avgGross20: number | null;
  /** Nº de holes-in-one (gross 1 em par 3/4) nos scorecards do jogador.
   *  Gerado por enrich-players.js. Ausente em stats antigos → tratar como 0. */
  aces?: number;
}

export type PlayerStatsDb = Record<string, PlayerStats>;

/** Dias desde a última ronda (calculado a partir de lastRoundDate) */
export function daysSince(ps: PlayerStats | undefined): number | null {
  if (!ps?.lastRoundDate) return null;
  const d = new Date(ps.lastRoundDate).getTime();
  if (isNaN(d)) return null;
  return Math.round((Date.now() - d) / 86400000);
}

/** Uma falha passageira (502, rede) devolve `{}` mas NÃO fica guardada — a
 *  chamada seguinte tenta outra vez (10/11/2026, `memoAsync`). Um 404 é
 *  «ficheiro não existe» e fica. */
const _load = memoAsync<PlayerStatsDb>(
  async () => {
    const db = await cachedFetchJson<PlayerStatsDb>("/player-stats.json");
    if (!db) console.warn("player-stats.json not found — sidebar enhancements disabled");
    return db ?? {};
  },
  { fallback: (e) => { console.warn("Failed to load player-stats.json:", e); return {}; } },
);

export function loadPlayerStats(): Promise<PlayerStatsDb> {
  return _load();
}
